                    i += 2
                    continue
                if s[i] == '"':
                    closed = True
                    break
                i += 1
            if not closed:
                return False
            i += 1
            continue
        if c in opens:
            stack.append(c)
        elif c in pairs:
            if not stack or stack[-1] != pairs[c]:
                return False
            stack.pop()
        i += 1
    return not stack
